function vstUpdateTextures_Init( ctxt )
{
	var oCmd;
	oCmd = ctxt.Source;
	oCmd.Description = "updates all textures in the scene";
	oCmd.Tooltip = "undefined";
	oCmd.ReturnValue = true;

	return true;
}

function vstUpdateTextures_Execute(  )
{

	Application.LogMessage("vstUpdateTextures_Execute called");
	logmessage ("*****************************");
	vproject = XSIUtils.Environment("VProject");
	staging = vproject.match ("staging");
	if (!staging)
	{
		mainPath = vproject;
	}
	else
	{
		mainPath = vproject.replace ("staging", "main");
	}
	contentPath = mainPath.replace ("game", "content");
	//logmessage ("Local Content Path: " + contentPath);

	fso = new ActiveXObject("Scripting.FileSystemObject");
	
	//get all the images in the scene
	oSources = EnumElements("Sources.Image");
	//logmessage("Found "+ oSources.count +" Image Sources");
	for (i=0; i<oSources.count; i++)
	{
	texPath = GetValue (oSources(i)+".Filename");
	texName = GetValue (oSources(i)+".Name");
	//logmessage (texName);
	//logmessage ("NAME: " + oSources(i));
	//match on materialsrc. This is a kind of cheesey way to determine if there is even a chance to find the texture
		if (texPath.match(/materialsrc/i))
		{
		texContentSplit = texPath.split (/materialsrc/i);
		localPath = contentPath + "\\materialsrc" + texContentSplit[1];
		//logmessage ("*SCENEPATH: " + texPath); 
		//logmessage ("*LOCAL PATH: "+ localPath); 
		vstP4sync (localPath);
		//after the texture is sync'ed set the source to point to the local path
		SetValue (oSources(i) +".Filename", localPath);
		//ok after the sync see if the file exists
		exists = fso.FileExists(localPath);
			if (!exists)
			//try looking in HL2 (lot of old models still have materials mapped to hl2)
			{
				findGame = contentPath.split("content");
				hl2Path = localPath.replace (findGame[1], "\\hl2");
				//logmessage ("***HL2path: " + hl2Path);
				vstP4sync (hl2Path);
				SetValue (oSources(i) +".Filename", hl2Path);
				exists = fso.FileExists(hl2Path);
				if (!exists)
					logmessage (hl2Path + " does not exist in source tree");
			}
		}	
	}
	
	return true;
}

